import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Dhf_H6O0.js";const p=JSON.parse('{"title":"Starting the Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"using-the-app/start-gateway.md","filePath":"using-the-app/start-gateway.md"}'),n={name:"using-the-app/start-gateway.md"};function i(s,e,l,h,g,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="starting-the-gateway" tabindex="-1">Starting the Gateway <a class="header-anchor" href="#starting-the-gateway" aria-label="Permalink to &quot;Starting the Gateway&quot;">​</a></h1><p>The gateway is the core of MCPBehindIT. It runs inside a Docker container and makes your MCP servers available over HTTP.</p><h2 id="starting" tabindex="-1">Starting <a class="header-anchor" href="#starting" aria-label="Permalink to &quot;Starting&quot;">​</a></h2><ol><li>Go to <strong>Home</strong> (Dashboard).</li><li>Make sure the <strong>DOCKER</strong> indicator is green (Reachable).</li><li>Click <strong>Start</strong>.</li></ol><h3 id="what-happens-behind-the-scenes" tabindex="-1">What happens behind the scenes <a class="header-anchor" href="#what-happens-behind-the-scenes" aria-label="Permalink to &quot;What happens behind the scenes&quot;">​</a></h3><ol><li><strong>Config generation</strong> — MCPBehindIT creates a <code>config.json</code> file from your enabled server definitions.</li><li><strong>Image pull</strong> (first time only) — The gateway Docker image (~200 MB) is downloaded. A progress log shows the download status.</li><li><strong>Container creation</strong> — A Docker container named <code>mindbehind-mcpo</code> is created with: <ul><li>Your generated config mounted at <code>/data/config.json</code></li><li>The configured HTTP port published (default: 8000)</li><li>Any OAuth callback ports published</li><li>Optional Docker socket access (for catalog servers that use <code>docker run</code>)</li><li>Optional document folder bind (for Local RAG)</li></ul></li><li><strong>Health check</strong> — MCPBehindIT polls the container until the gateway responds to HTTP requests.</li><li><strong>Ready</strong> — The status badge turns green and the Clients tab becomes available.</li></ol><h2 id="stopping" tabindex="-1">Stopping <a class="header-anchor" href="#stopping" aria-label="Permalink to &quot;Stopping&quot;">​</a></h2><p>Click <strong>Stop</strong> on the Dashboard. The container is removed (not just paused). Your server definitions and settings are preserved — they live outside the container.</p><h2 id="apply-restart" tabindex="-1">Apply &amp; Restart <a class="header-anchor" href="#apply-restart" aria-label="Permalink to &quot;Apply &amp; Restart&quot;">​</a></h2><p>When you change server definitions (add, edit, delete, enable, or disable a server), you need to <strong>restart the gateway</strong> so it picks up the new config.</p><p>Click <strong>Apply &amp; Restart</strong> to:</p><ol><li>Stop the current container.</li><li>Regenerate the config file.</li><li>Create and start a fresh container with the updated config.</li></ol><div class="tip custom-block"><p class="custom-block-title">When do I need to restart?</p><ul><li>After adding, editing, or removing a server → <strong>Apply &amp; Restart</strong></li><li>After changing the gateway port in Settings → automatic restart</li><li>After changing Docker resource limits → <strong>Apply &amp; Restart</strong></li></ul><p>You do <strong>not</strong> need to restart when:</p><ul><li>Just viewing logs</li><li>Copying connection URLs</li><li>Indexing RAG documents (indexing runs inside the existing container)</li></ul></div><h2 id="gateway-logs" tabindex="-1">Gateway logs <a class="header-anchor" href="#gateway-logs" aria-label="Permalink to &quot;Gateway logs&quot;">​</a></h2><p>During startup, the progress log shows each step. If something goes wrong, look for error messages here. You can also check the <a href="./logs.html">Logs</a> page for the full container output.</p><h2 id="system-tray" tabindex="-1">System tray <a class="header-anchor" href="#system-tray" aria-label="Permalink to &quot;System tray&quot;">​</a></h2><p>MCPBehindIT adds an icon to your macOS menu bar (system tray). Right-click or click it to:</p><ul><li><strong>Show window</strong> — bring the app to the front</li><li><strong>Start mcpo</strong> — start the gateway</li><li><strong>Stop mcpo</strong> — stop the gateway</li><li><strong>Quit</strong> — stop the gateway and close the app</li></ul>',18)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
